/* Pixel Classroom Styling */
[hidden] {
  display: none !important;
}

:root {
  --bg-primary: #1e2430;
  --card-bg: #2d3748;
  --desk-wood: #c07a46;
  --desk-wood-empty: #8d562f;
  --desk-wood-shadow: #5c3417;
  --chalk-green: #234e38;
  --text-primary: #f7fafc;
  --text-muted: #cbd5e0;
  --accent-gold: #f6ad55;
  --accent-danger: #fc8181;
  --focus-ring: #63b3ed;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.classroom-card {
  background-color: var(--card-bg);
  border: 4px solid #1a202c;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.45), 0 0 0 2px var(--desk-wood-empty);
  border-radius: 8px;
  width: 100%;
  max-width: 540px;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.classroom-header {
  text-align: center;
}

.classroom-header h1 {
  font-size: 1.5rem;
  letter-spacing: 1px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.chalkboard {
  background-color: var(--chalk-green);
  border: 4px solid var(--desk-wood);
  border-radius: 4px;
  padding: 10px;
  text-align: center;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.5);
}

.chalk-text {
  color: #e2e8f0;
  font-weight: 700;
  letter-spacing: 3px;
  font-size: 1rem;
}

.controls-area {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  font-weight: 600;
  font-size: 1rem;
  color: var(--text-primary);
}

.input-row {
  display: flex;
  width: 100%;
}

#student-name-input {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 2px solid #4a5568;
  border-radius: 4px;
  background-color: #1a202c;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

#student-name-input:focus {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(99, 179, 237, 0.35);
}

.status-message {
  font-size: 0.9rem;
  min-height: 1.2rem;
  color: var(--accent-gold);
}

.status-message.error {
  color: var(--accent-danger);
}

.counter-area {
  display: flex;
  justify-content: center;
}

.counter-badge {
  background-color: #1a202c;
  padding: 8px 18px;
  border-radius: 9999px;
  font-size: 1.05rem;
  font-weight: 600;
  border: 2px solid var(--accent-gold);
  color: var(--text-primary);
}

.grid-wrapper {
  width: 100%;
  margin-top: 4px;
}

.classroom-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  width: 100%;
}

.desk-btn {
  appearance: none;
  background-color: var(--desk-wood-empty);
  border: 2px solid var(--desk-wood-shadow);
  border-bottom: 5px solid var(--desk-wood-shadow);
  border-radius: 6px;
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 74px;
  padding: 6px 4px;
  font-size: 0.95rem;
  text-align: center;
  transition: transform 0.08s ease, background-color 0.15s ease, border-color 0.15s ease;
  user-select: none;
}

.desk-btn:hover {
  background-color: #9f6236;
  transform: translateY(-2px);
}

.desk-btn:active {
  transform: translateY(2px);
  border-bottom-width: 2px;
}

.desk-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.desk-btn.seated {
  background-color: var(--desk-wood);
  border-color: #4a2810;
  border-bottom-color: #321808;
}

.desk-btn.seated:hover {
  background-color: #cf8651;
}

.desk-number {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.desk-name {
  font-size: 0.95rem;
  font-weight: 600;
  margin-top: 4px;
  word-break: break-word;
  max-width: 100%;
  line-height: 1.15;
}

.desk-status {
  font-size: 0.75rem;
  font-style: italic;
  color: #e2e8f0;
  opacity: 0.8;
  margin-top: 2px;
}

.classroom-footer {
  text-align: center;
  padding-top: 8px;
  border-top: 1px solid #4a5568;
}

.instruction-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.4;
}

@media (max-width: 420px) {
  .classroom-card {
    padding: 16px 12px;
    gap: 12px;
  }

  .classroom-grid {
    gap: 8px;
  }

  .desk-btn {
    min-height: 66px;
    padding: 4px 2px;
  }

  .desk-name {
    font-size: 0.85rem;
  }

  .desk-number {
    font-size: 0.7rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_ROWS = 3;
  const TOTAL_COLS = 4;
  const TOTAL_DESKS = TOTAL_ROWS * TOTAL_COLS;

  // State: array of 12 slots, null if empty or string with student name
  const desks = new Array(TOTAL_DESKS).fill(null);

  const gridContainer = document.getElementById('classroom-grid');
  const studentNameInput = document.getElementById('student-name-input');
  const filledCounter = document.getElementById('filled-counter');
  const totalCounter = document.getElementById('total-counter');
  const statusMessage = document.getElementById('status-message');

  totalCounter.textContent = TOTAL_DESKS.toString();

  function setStatus(message, isError = false) {
    statusMessage.textContent = message;
    if (isError) {
      statusMessage.classList.add('error');
    } else {
      statusMessage.classList.remove('error');
    }
  }

  function updateOccupancy() {
    const filledCount = desks.filter(name => name !== null).length;
    filledCounter.textContent = filledCount.toString();
  }

  function renderDesk(index) {
    const deskBtn = document.getElementById(`desk-${index}`);
    if (!deskBtn) return;

    const studentName = desks[index];
    const rowNum = Math.floor(index / TOTAL_COLS) + 1;
    const colNum = (index % TOTAL_COLS) + 1;

    if (studentName) {
      deskBtn.classList.add('seated');
      deskBtn.setAttribute('aria-label', `Desk Row ${rowNum} Col ${colNum}: Seated with ${studentName}. Click to clear seat.`);
      deskBtn.innerHTML = `
        <span class="desk-number">R${rowNum}C${colNum}</span>
        <span class="desk-name">${studentName}</span>
        <span class="desk-status">Seated</span>
      `;
    } else {
      deskBtn.classList.remove('seated');
      deskBtn.setAttribute('aria-label', `Desk Row ${rowNum} Col ${colNum}: Empty. Click to seat student.`);
      deskBtn.innerHTML = `
        <span class="desk-number">R${rowNum}C${colNum}</span>
        <span class="desk-name">(Empty)</span>
      `;
    }
  }

  function handleDeskClick(index) {
    const currentStudent = desks[index];
    const rowNum = Math.floor(index / TOTAL_COLS) + 1;
    const colNum = (index % TOTAL_COLS) + 1;

    // If desk is already seated, clicking it clears it
    if (currentStudent !== null) {
      desks[index] = null;
      renderDesk(index);
      updateOccupancy();
      setStatus(`Cleared ${currentStudent} from Desk R${rowNum}C${colNum}.`);
      return;
    }

    // If desk is empty, seat student if name is entered
    const candidateName = studentNameInput.value.trim();
    if (!candidateName) {
      setStatus('Please type a student name first to assign a seat.', true);
      studentNameInput.focus();
      return;
    }

    desks[index] = candidateName;
    renderDesk(index);
    updateOccupancy();
    setStatus(`Seated ${candidateName} at Desk R${rowNum}C${colNum}.`);
    studentNameInput.value = '';
    studentNameInput.focus();
  }

  // Initialize 3x4 grid buttons
  for (let i = 0; i < TOTAL_DESKS; i++) {
    const deskBtn = document.createElement('button');
    deskBtn.type = 'button';
    deskBtn.id = `desk-${i}`;
    deskBtn.className = 'desk-btn';
    deskBtn.dataset.index = i.toString();

    deskBtn.addEventListener('click', () => {
      handleDeskClick(i);
    });

    gridContainer.appendChild(deskBtn);
    renderDesk(i);
  }

  updateOccupancy();
});
